import java.util.*;
class Solution {
    public int subarraySum(int[] nums,int k){
        Map<Long,Integer> seen=new HashMap<>();
        seen.put(0L,1);
        long sum=0;
        int count=0;
        for(int x:nums){
            sum+=x;
            count+=seen.getOrDefault(sum-k,0);
            seen.put(sum,seen.getOrDefault(sum,0)+1);
        }
        return count;
    }
}

